<script type="module">
import * as THREE from 'three';

// ---------------------------------------------------------------- palette
// Taken from the print: deep Prussian blue waves, cream foam/snow,
// tan/ochre boats, warm beige sky grading to muted grey at the horizon.
const PAL = {
  waveDeep:   0x16324f,
  waveMid:    0x24507a,
  foam:       0xf2ead8,
  snow:       0xf7f2e6,
  boat:       0xb5854f,
  boatDark:   0x8a6238,
  skyTop:     0xe8dcc0,
  skyHorizon: 0x9aa4ae,
  water:      0x2e5f8a,
  fujiBase:   0x46586a,
  cloud:      0xf5efe0,
  rower:      0x5a4632,
  seal:       0xa63a2b,
};

// ---------------------------------------------------------------- renderer
const container = document.getElementById('app');
const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
container.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(PAL.skyHorizon, 30, 70);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 200);
camera.position.set(0, 4.5, 17);
camera.lookAt(0, 2.5, 0);

scene.add(new THREE.AmbientLight(0xffffff, 0.65));
const sun = new THREE.DirectionalLight(0xfff0d0, 1.1);
sun.position.set(6, 12, 8);
scene.add(sun);

// ---------------------------------------------------------------- sky
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(90, 32, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    uniforms: {
      top:    { value: new THREE.Color(PAL.skyTop) },
      bottom: { value: new THREE.Color(PAL.skyHorizon) },
    },
    vertexShader: `
      varying vec3 vW;
      void main() {
        vW = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * viewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      uniform vec3 top; uniform vec3 bottom; varying vec3 vW;
      void main() {
        float h = normalize(vW).y;
        vec3 c = mix(bottom, top, clamp(h * 1.6, 0.0, 1.0));
        gl_FragColor = vec4(c, 1.0);
      }`,
  })
);
scene.add(sky);

